 * See LICENSE in the root of the software repository for the full text of the License.
 */

// ForeachAddcdivScalarList AscendC Kernel
// Computes: output = x1 + x2 / x3 * scalarValue
//
// Supports float32 (direct compute), float16/bfloat16 (cast up to float32)
// The host loops over tensor lists and launches this kernel once per tensor group.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelForeachAddcdivScalarList {
public:
    __aicore__ inline KernelForeachAddcdivScalarList() {}

    __aicore__ inline void Init(GM_ADDR x1GmAddr, GM_ADDR x2GmAddr, GM_ADDR x3GmAddr, GM_ADDR yGmAddr,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                float scalarValue)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            x1Gm.SetGlobalBuffer((__gm__ T *)x1GmAddr + offset, formerLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2GmAddr + offset, formerLength);
            x3Gm.SetGlobalBuffer((__gm__ T *)x3GmAddr + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)yGmAddr + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            x1Gm.SetGlobalBuffer((__gm__ T *)x1GmAddr + offset, tailLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2GmAddr + offset, tailLength);
            x3Gm.SetGlobalBuffer((__gm__ T *)x3GmAddr + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)yGmAddr + offset, tailLength);
        }

        this->tileLength = tileLength;
        this->scalarValue = scalarValue;

        // Input queues for x1, x2, x3
        pipe.InitBuffer(inQueueX1, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueX2, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueX3, BUFFER_NUM, tileLength * sizeof(T));
        // Output queue
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (!std::is_same_v<T, float>) {
            // fp16/bf16: need fp32 intermediate buffers for upcast
            pipe.InitBuffer(castBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(castBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(castBuf3, tileLength * sizeof(float));
        } else {
            // fp32: one intermediate buffer for Div result
            pipe.InitBuffer(tmpBuf, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if (this->blockLength == 0) {
            return;
        }
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        CopyIn(tileNum - 1, tailTileLength);
        Compute(tileNum - 1, tailTileLength);
        CopyOut(tileNum - 1, tailTileLength);
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};

        AscendC::LocalTensor<T> x1Local = inQueueX1.AllocTensor<T>();
        AscendC::DataCopyPad(x1Local, x1Gm[progress * this->tileLength], copyParams, padParams);
        inQueueX1.EnQue(x1Local);

        AscendC::LocalTensor<T> x2Local = inQueueX2.AllocTensor<T>();
        AscendC::DataCopyPad(x2Local, x2Gm[progress * this->tileLength], copyParams, padParams);
        inQueueX2.EnQue(x2Local);

        AscendC::LocalTensor<T> x3Local = inQueueX3.AllocTensor<T>();
        AscendC::DataCopyPad(x3Local, x3Gm[progress * this->tileLength], copyParams, padParams);
        inQueueX3.EnQue(x3Local);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> x1Local = inQueueX1.DeQue<T>();
        AscendC::LocalTensor<T> x2Local = inQueueX2.DeQue<T>();
        AscendC::LocalTensor<T> x3Local = inQueueX3.DeQue<T>();

        if constexpr (std::is_same_v<T, float>) {
            // float32: direct compute
            // tmp = x2 / x3
            AscendC::LocalTensor<float> tmpLocal = tmpBuf.Get<float>();
            AscendC::Div(tmpLocal, x2Local, x3Local, curTileLength);
            // tmp = tmp * scalar
            AscendC::Muls(tmpLocal, tmpLocal, this->scalarValue, curTileLength);
            // output = x1 + tmp
            AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
            AscendC::Add(yLocal, x1Local, tmpLocal, curTileLength);
            outQueueY.EnQue<float>(yLocal);
        } else {
            // fp16/bf16: Cast up → Compute in fp32 → Cast down
            AscendC::LocalTensor<float> x1F32 = castBuf1.Get<float>();
            AscendC::LocalTensor<float> x2F32 = castBuf2.Get<float>();
            AscendC::LocalTensor<float> x3F32 = castBuf3.Get<float>();

            // Cast inputs to float32
            AscendC::Cast(x1F32, x1Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(x2F32, x2Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(x3F32, x3Local, AscendC::RoundMode::CAST_NONE, curTileLength);

            // Compute in float32: x2F32 = x2F32 / x3F32
            AscendC::Div(x2F32, x2F32, x3F32, curTileLength);
            // Compute: x2F32 = x2F32 * scalar
            AscendC::Muls(x2F32, x2F32, this->scalarValue, curTileLength);
            // Compute: x1F32 = x1F32 + x2F32  (output in x1F32)
            AscendC::Add(x1F32, x1F32, x2F32, curTileLength);

            // Cast down to original dtype and enqueue output
            AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
            if constexpr (std::is_same_v<T, half> || std::is_same_v<T, bfloat16_t>) {
                AscendC::Cast(yLocal, x1F32, AscendC::RoundMode::CAST_ROUND, curTileLength);
            } else {
                AscendC::Cast(yLocal, x1F32, AscendC::RoundMode::CAST_NONE, curTileLength);
            }
            outQueueY.EnQue<T>(yLocal);
        }

        inQueueX1.FreeTensor(x1Local);
        inQueueX2.FreeTensor(x2Local);
        inQueueX3.FreeTensor(x3Local);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX1;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX2;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX3;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf3;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
    AscendC::GlobalTensor<T> x1Gm;
    AscendC::GlobalTensor<T> x2Gm;
    AscendC::GlobalTensor<T> x3Gm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
    float scalarValue;
};

extern "C" __global__ __aicore__ void foreach_addcdiv_scalar_list(
    GM_ADDR x1, GM_ADDR x2, GM_ADDR x3, GM_ADDR y,
    int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength,
    float scalarValue)
{
    // Note: dtype is determined by the host — each kernel launch handles one dtype.
    // The host selects the correct instantiation when calling EXEC_KERNEL_CMD.
    // The kernel template is selected at compile time by EXEC_KERNEL_CMD mechanism.
    // We default to half for the kernel symbol visibility.
    KernelForeachAddcdivScalarList<half> op;
    op.Init(x1, x2, x3, y, formerNum, formerLength, tailLength, tileLength, scalarValue);
    op.Process();
}
