// ForeachAddcdivScalarList Host 端
// 遍历 tensor 列表，为每个 tensor group 计算 tiling 并启动 kernel

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_foreach_addcdiv_scalar_list.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

std::vector<at::Tensor> foreach_addcdiv_scalar_list(
    const std::vector<at::Tensor>& x1,
    const std::vector<at::Tensor>& x2,
    const std::vector<at::Tensor>& x3,
    const at::Tensor& scalars)
{
    int64_t listLen = static_cast<int64_t>(x1.size());
    TORCH_CHECK(listLen == static_cast<int64_t>(x2.size()),
                "foreach_addcdiv_scalar_list: x1 and x2 must have same length");
    TORCH_CHECK(listLen == static_cast<int64_t>(x3.size()),
                "foreach_addcdiv_scalar_list: x1 and x3 must have same length");
    TORCH_CHECK(listLen == scalars.numel(),
                "foreach_addcdiv_scalar_list: scalars length must match list length");

    // ---- 获取硬件参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- 准备 scalars 值 (移到 CPU 供 host 端读取) ----
    at::Tensor scalarsCpu = scalars.to(at::kCPU).to(at::kFloat).contiguous();
    const float* scalarsData = scalarsCpu.const_data_ptr<float>();

    std::vector<at::Tensor> outputs;
    outputs.reserve(static_cast<size_t>(listLen));

    for (int64_t k = 0; k < listLen; ++k) {
        const at::Tensor& t1 = x1[static_cast<size_t>(k)];
        const at::Tensor& t2 = x2[static_cast<size_t>(k)];
        const at::Tensor& t3 = x3[static_cast<size_t>(k)];
        float scalarValue = scalarsData[static_cast<size_t>(k)];

        // ---- 输入校验 ----
        auto scalarType = t1.scalar_type();
        TORCH_CHECK(scalarType == at::kHalf || scalarType == at::kBFloat16 ||
                    scalarType == at::kFloat,
                    "foreach_addcdiv_scalar_list: only float16, bfloat16, float32 supported, got ",
                    scalarType);
        TORCH_CHECK(t1.scalar_type() == t2.scalar_type() && t1.scalar_type() == t3.scalar_type(),
                    "foreach_addcdiv_scalar_list: all input tensors must have same dtype");
        TORCH_CHECK(t1.sizes() == t2.sizes() && t1.sizes() == t3.sizes(),
                    "foreach_addcdiv_scalar_list: corresponding tensors must have same shape");
        TORCH_CHECK(t1.is_contiguous() && t2.is_contiguous() && t3.is_contiguous(),
                    "foreach_addcdiv_scalar_list: input tensors must be contiguous");

        int64_t totalLength = t1.numel();
        int64_t dtypeSize = static_cast<int64_t>(t1.element_size());

        auto output = at::empty_like(t1);

        if (totalLength == 0) {
            outputs.push_back(output);
            continue;
        }

        // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
        int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
        int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                        / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

        int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
        int64_t formerNum = usedCoreNum - 1;
        int64_t formerLength = totalLengthCoreAlign;
        int64_t tailLengthVal = totalLength - formerNum * formerLength;

        // ---- UB 级 tiling (核内切分, 32B 对齐) ----
        // bufferCoefficient 从 UB 分配表推导:
        //   fp16/bf16: inQueueX1(2*2) + inQueueX2(2*2) + inQueueX3(2*2)
        //              + outQueueY(2*2) + castBuf1(4) + castBuf2(4) + castBuf3(4) = 28
        //   fp32: inQueueX1(2*4) + inQueueX2(2*4) + inQueueX3(2*4)
        //          + outQueueY(2*4) + tmpBuf(4) = 36
        int64_t bufferCoefficient;
        if (dtypeSize == 2) {
            // fp16/bf16: 3 cast buffers for upcast to fp32
            bufferCoefficient = 28;
        } else {
            // fp32: 1 tmp buffer for Div result
            bufferCoefficient = 36;
        }

        int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
        int64_t alignElements = 32 / dtypeSize;
        if (alignElements < 1) {
            alignElements = 1;
        }
        int64_t tileLength = (maxTileElements / alignElements) * alignElements;

        uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

        // EXEC_KERNEL_CMD 硬约束: 所有参数必须是左值
        EXEC_KERNEL_CMD(foreach_addcdiv_scalar_list, blockDim,
                        t1, t2, t3, output,
                        formerNum, formerLength, tailLengthVal, tileLength,
                        dtypeSize, scalarValue);

        outputs.push_back(output);
    }

    return outputs;
}

}  // namespace ascend_kernel
