// ForeachAddcdivScalarList AscendC Kernel
// Computes: output = x1 + x2 / x3 * scalarValue
//
// For fp32: direct compute using AscendC vector APIs.
// For fp16/bf16: compute in fp32 for numerical stability, then cast down.
// This matches PyTorch NPU's internal fp32 accumulation for fp16 operations.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelForeachAddcdivScalarList {
public:
    __aicore__ inline KernelForeachAddcdivScalarList() {}

    __aicore__ inline void Init(GM_ADDR x1GmAddr, GM_ADDR x2GmAddr, GM_ADDR x3GmAddr, GM_ADDR yGmAddr,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                float scalarValue)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            x1Gm.SetGlobalBuffer((__gm__ T *)x1GmAddr + offset, formerLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2GmAddr + offset, formerLength);
            x3Gm.SetGlobalBuffer((__gm__ T *)x3GmAddr + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)yGmAddr + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            x1Gm.SetGlobalBuffer((__gm__ T *)x1GmAddr + offset, tailLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2GmAddr + offset, tailLength);
            x3Gm.SetGlobalBuffer((__gm__ T *)x3GmAddr + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)yGmAddr + offset, tailLength);
        }

        this->tileLength = tileLength;
