            AscendC::LocalTensor<float> tmpLocal = tmpBuf.Get<float>();
            AscendC::Div(tmpLocal, x2Local, x3Local, curTileLength);
            AscendC::Muls(tmpLocal, tmpLocal, this->scalarValue, curTileLength);
