            AscendC::LocalTensor<float> x1F32 = castBuf1.Get<float>();
            AscendC::LocalTensor<float> x2F32 = castBuf2.Get<float>();
            AscendC::LocalTensor<float> x3F32 = castBuf3.Get<float>();

            AscendC::Cast(x1F32, x1Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(x2F32, x2Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(x3F32, x3Local, AscendC::RoundMode::CAST_NONE, curTileLength);

